DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='get_public_event'; d:=replace(d,'''allows_minors'', e.allows_minors, ''min_age'', e.min_age, ''price_cents'', e.price_cents)', '''allows_minors'', e.allows_minors, ''min_age'', e.min_age, ''price_cents'', e.price_cents, ''ticket_tiers'', (SELECT coalesce(jsonb_agg(t || jsonb_build_object(''sold'', (SELECT coalesce(sum(1+r.plus_ones),0) FROM public.rsvps r WHERE r.event_id=e.id AND r.tier_id=t->>''id'' AND r.status=''going'' AND r.merged_into_rsvp_id IS NULL))),''[]''::jsonb) FROM jsonb_array_elements(e.ticket_tiers) t))'); IF d NOT LIKE '%''ticket_tiers''%' THEN RAISE EXCEPTION 'public tier patch did not match'; END IF; EXECUTE d; END $$;